 {for(var i=0;i<200;i++){if(done())return;var p=P(g);if(p is{PlayerSeat:0}&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else if(p is{PlayerSeat:0,Kind:DecisionKind.RescueDying or DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.Nullification})Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"pass"or"take-damage"or"let-die");else if(p is{PlayerSeat:0,Kind:DecisionKind.PlayCard})End(g);else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Zhang Qi Ying boundary missing: "+JsonSerializer.Serialize(new{Pending=P(g),Stack=g.ResolutionStack,Players=Enumerable.Range(0,4).Select(s=>V(g,s))}));}
